});

const BASE = 'https://api.thepulseapi.com/api/v1';

async function post<T>(path: string, body: Record<string, unknown>): Promise<T> {
  const response = await fetch(`${BASE}${path}`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-api-key': process.env.PULSE_API_KEY!,
    },
    body: JSON.stringify({ organizationId: process.env.PULSE_ORG_ID, ...body }),
    // fetch has no default timeout, and a hung ranking call should not hold a request.
    signal: AbortSignal.timeout(5000),
  });

  if (!response.ok) throw new Error(`PULSE ${path}: ${response.status}`);
  return response.json() as Promise<T>;
}

export const track = (sessionId: string, signals: unknown[]) =>
  post('/track', { sessionId, signals });

export const rankedCatalog = (sessionId: string, limit = 24) =>
  post('/catalog/ranked', { sessionId, limit });

from django.shortcuts import render
from .pulse import pulse


def category(request, slug):
    # The browser owns the session. Read it rather than minting a second one for the
    # same shopper: two session ids means the inference starts from nothing twice.
    session_id = request.COOKIES.get("pulse_session")
    products = []

    if session_id:
        try:
            products = pulse.ranked_catalog(session_id, limit=24, categorySlug=slug)["items"]
        except Exception:
            # Ranking is an enhancement. A page that fails to render because personalisation
            # was slow is worse than a page in catalogue order.
            products = []

    return render(request, "category.html", {"products": products or default_order(slug)})

